import osimport tokenizedef fix_quotes_in_file(file_path):    with open(file_path, "rb") as f:        tokens = list(tokenize.tokenize(f.readline))    new_tokens = []    for toknum, tokval, start, end, line in tokens:        if toknum == tokenize.STRING:            if tokval.startswith('"') or tokval.startswith('"""'):                # Преобразуем только строковые литералы с двойными кавычками                tokval = "'" + tokval[1:-1].replace("'", "\\'") + "'"        new_tokens.append((toknum, tokval))    with open(file_path, "w", encoding="utf-8") as f:        f.write(tokenize.untokenize(new_tokens))def process_directory(directory):    for root, _, files in os.walk(directory):        for filename in files:            if filename.endswith(".py") and filename != "fix_quotes.py":                fix_quotes_in_file(os.path.join(root, filename))if __name__ == "__main__":    process_directory(".")